    const complement = target - nums[i];
    if (seen.has(complement)) return [seen.get(complement), i];
    seen.set(nums[i], i);
  }
  return [];
}
```

--- Accepted Answer ---
Note this isn't thread-safe as written — wrap it if you need concurrent access.

