```javascript
function useFetch(url) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    fetch(url).then(r => r.json()).then(json => {
      if (!cancelled) { setData(json); setLoading(false); }
    });
    return () => { cancelled = true; };
  }, [url]);

  return { data, loading };
}
```

