Sharing our internal standard for this pattern so new hires have something to copy from.

```python
import json, functools

def redis_cache(ttl=60):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args):
            key = f"{fn.__name__}:{args}"
            cached = redis_client.get(key)
            if cached:
                return json.loads(cached)
            result = fn(*args)
            redis_client.setex(key, ttl, json.dumps(result))
            return result
        return wrapper
    return decorator
```

