This came up in code review a few times, so here's the version we settled on.

```python
import json, functools

def redis_cache(ttl=60):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args):
            key = f"{fn.__name__}:{args}"
            cached = redis_client.get(key)
            if cached:
                return json.loads(cached)
            result = fn(*args)
            redis_client.setex(key, ttl, json.dumps(result))
            return result
        return wrapper
    return decorator
```

content:
Reference snippet - Redis caching wrapper in Python

This came up in code review a few times, so here's the version we settled on.

```python
import json, functools

def redis_cache(ttl=60):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args):
            key = f"{fn.__name__}:{args}"
            cached = redis_client.get(key)
            if cached:
                return json.loads(cached)
            result = fn(*args)
            redis_client.setex(key, ttl, json.dumps(result))
            return result
        return wrapper
    return decorator
```

