Quick reference for anyone who needs this pattern again.

```javascript
class EventBus {
  constructor() { this.listeners = {}; }
  on(event, cb) {
    (this.listeners[event] ??= []).push(cb);
  }
  emit(event, payload) {
    (this.listeners[event] || []).forEach(cb => cb(payload));
  }
}
```

content:
Reference snippet - Observer / pub-sub pattern in JavaScript

Quick reference for anyone who needs this pattern again.

```javascript
class EventBus {
  constructor() { this.listeners = {}; }
  on(event, cb) {
    (this.listeners[event] ??= []).push(cb);
  }
  emit(event, payload) {
    (this.listeners[event] || []).forEach(cb => cb(payload));
  }
}
```

body:
Quick reference for anyone who needs this pattern again.

```javascript
function twoSum(nums, target) {
  const seen = new Map();
  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];
    if (seen.has(complement)) return [seen.get(complement), i];
    seen.set(nums[i], i);
  }
  return [];
}
```

content:
Simple JavaScript implementation of Two-sum problem

Quick reference for anyone who needs this pattern again.

```javascript
function twoSum(nums, target) {
  const seen = new Map();
  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];
    if (seen.has(complement)) return [seen.get(complement), i];
    seen.set(nums[i], i);
  }
  return [];
}
```

